// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";

/// @title MessageQueueConsumer - Processes templated messages from an off-chain queue
/// @notice Uses feature flags to control message rendering behavior
contract MessageQueueConsumer is Ownable {

    struct FeatureFlags {
        bool enableTemplateCache;
        bool enableDynamicRouting;
        bool allowNestedTemplates;
        uint8 maxTemplateDepth;
    }

    struct MessageTemplate {
        string pattern;
        address author;
        uint256 createdAt;
        bool verified;
    }

    struct QueueMessage {
        bytes32 messageId;
        address sender;
        string templateKey;
        bytes payload;
        uint256 timestamp;
    }

    mapping(string => MessageTemplate) public templates;
    mapping(bytes32 => bool) public processedMessages;
    mapping(address => bool) public authorizedProducers;

    FeatureFlags public flags;
    address public templateRenderer;

    event MessageProcessed(bytes32 indexed messageId, address indexed sender, string result);
    event TemplateRegistered(string key, address author);
    event RendererUpdated(address oldRenderer, address newRenderer);

    modifier onlyProducer() {
        require(authorizedProducers[msg.sender], "Not authorized producer");
        _;
    }

    constructor(address _renderer) Ownable(msg.sender) {
        templateRenderer = _renderer;
        flags = FeatureFlags({
            enableTemplateCache: true,
            enableDynamicRouting: false,
            allowNestedTemplates: false,
            maxTemplateDepth: 3
        });
    }

    function setFeatureFlags(FeatureFlags calldata _flags) external onlyOwner {
        flags = _flags;
    }

    function addProducer(address producer) external onlyOwner {
        authorizedProducers[producer] = true;
    }

    function removeProducer(address producer) external onlyOwner {
        authorizedProducers[producer] = false;
    }

    function registerTemplate(string calldata key, string calldata pattern) external {
        require(bytes(pattern).length > 0, "Empty pattern");
        require(bytes(pattern).length <= 1024, "Pattern too long");
        templates[key] = MessageTemplate({
            pattern: pattern,
            author: msg.sender,
            createdAt: block.timestamp,
            verified: false
        });
        emit TemplateRegistered(key, msg.sender);
    }

    function verifyTemplate(string calldata key) external onlyOwner {
        require(bytes(templates[key].pattern).length > 0, "Template not found");
        templates[key].verified = true;
    }

    /// @notice Core message processing - resolves template and renders
    function processMessage(QueueMessage calldata msg_) external onlyProducer {
        require(!processedMessages[msg_.messageId], "Already processed");
        require(msg_.timestamp + 1 hours >= block.timestamp, "Message expired");

        processedMessages[msg_.messageId] = true;

        string memory rendered = _resolveAndRender(msg_.templateKey, msg_.payload);
        emit MessageProcessed(msg_.messageId, msg_.sender, rendered);
    }

    function _resolveAndRender(
        string memory templateKey,
        bytes memory payload
    ) internal returns (string memory) {
        MessageTemplate storage tmpl = templates[templateKey];
        require(bytes(tmpl.pattern).length > 0, "Template not found");

        if (!flags.allowNestedTemplates) {
            return _renderFlat(tmpl.pattern, payload);
        }

        return _renderNested(tmpl.pattern, payload, 0);
    }

    function _renderFlat(
        string memory pattern,
        bytes memory payload
    ) internal returns (string memory) {
        // Delegate rendering to external renderer contract
        (bool success, bytes memory result) = templateRenderer.delegatecall(
            abi.encodeWithSignature("render(string,bytes)", pattern, payload)
        );
        require(success, "Render failed");
        return abi.decode(result, (string));
    }

    function _renderNested(
        string memory pattern,
        bytes memory payload,
        uint8 depth
    ) internal returns (string memory) {
        require(depth < flags.maxTemplateDepth, "Max depth exceeded");

        // When dynamic routing is enabled, payload can specify renderer
        address renderer = templateRenderer;
        if (flags.enableDynamicRouting && payload.length >= 20) {
            renderer = _extractRendererFromPayload(payload);
        }

        (bool success, bytes memory result) = renderer.delegatecall(
            abi.encodeWithSignature("renderNested(string,bytes,uint8)", pattern, payload, depth)
        );
        require(success, "Nested render failed");
        return abi.decode(result, (string));
    }

    function _extractRendererFromPayload(bytes memory payload) internal pure returns (address) {
        require(payload.length >= 20, "Invalid payload for routing");
        address extracted;
        assembly {
            extracted := mload(add(payload, 20))
        }
        return extracted;
    }

    function updateRenderer(address newRenderer) external onlyOwner {
        require(newRenderer != address(0), "Zero address");
        require(newRenderer.code.length > 0, "Not a contract");
        emit RendererUpdated(templateRenderer, newRenderer);
        templateRenderer = newRenderer;
    }

    /// @notice Batch process for efficiency
    function processBatch(QueueMessage[] calldata messages) external onlyProducer {
        for (uint i = 0; i < messages.length; i++) {
            if (!processedMessages[messages[i].messageId]) {
                processedMessages[messages[i].messageId] = true;
                string memory rendered = _resolveAndRender(
                    messages[i].templateKey,
                    messages[i].payload
                );
                emit MessageProcessed(messages[i].messageId, messages[i].sender, rendered);
            }
        }
    }
}
